這是一個典型的**最短路徑問題 (Shortest Path Problem)**，可以使用 **BFS (廣度優先搜尋)** 來解決。由於題目要求的「成本」是所有經過狀態的數值總和，我們需要記錄每個數字到達時的最小累積成本。

```python
import collections

def minOperations(n: int, m: int):
    # 檢查目標數 m 是否為質數，若是則無法達成
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    if is_prime(m):
        return -1

    # BFS 初始化
    # queue stores (current_value, current_total_cost)
    queue = collections.deque([(n, n)])
    visited = {n: n}  # value -> min_cost_to_reach_this_value

    while queue:
        curr, curr_cost = queue.popleft()

        if curr == m:
            return curr_cost

        s_curr = list(str(curr))
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # 嘗試增加與減少
            for diff in [1, -1]:
                new_digit = digit + diff
                if 0 <= new_digit <= 9:
                    # 防止進位導致數字長度改變或前導零（題目要求相同位數）
                    if i == 0 and new_digit == 0 and len(s_curr) > 1:
                        continue

                    new_val = int("".join(map(str, s_curr))) # 這裡邏輯簡化，直接計算新值
                    # 重新計算 new_val 以確保正確性
                    temp_list = list(s_curr)
                    temp_list[i] = str(new_digit)
                    new_val = int("".join(temp_list))

                    # 條件檢查：長度不變、非質數、未被更低成本訪問過
                    if len(str(new_val)) == len(str(n)):
                        if not is_prime(new_val):
                            new_cost = curr_cost + new_val
                            if new_val not in visited or new_cost < visited[new_val]:
                                visited[new_val] = new_cost
                                queue.append((new_val, new_cost))

    return -1
```

**注意：** 由於這題的成本是「數值總和」，且 $n, m < 10^4$，BFS 是最穩定的解法。若搜尋空間過大，可考慮使用 Dijkstra 演算法（將 `queue` 改為 `heapq`）。

這是一個典型的最短路徑問題，可以使用 **Dijkstra 演算法** 來解決。因為我們需要最小化「經過所有數字的總和」，且每個狀態（數字）轉到下一個狀態的權重是該狀態的值本身。

```python
import heapq

def minOperations(n: int, m: int) -> int:
    # 預處理質數判斷 (範圍 до 10^4)
    limit = 10001
    is_prime = [True] * limit
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, limit, p):
                is_prime[i] = False

    # 如果起始值或目標值是質數，直接回傳 -1
    if is_prime[n] or is_prime[m]:
        return -1

    # Dijkstra 演算法
    # heap 儲存 (累積成本, 當前數字)
    pq = [(n, n)]
    # dist 紀錄到每個數字的最小成本
    dist = {n: n}

    while pq:
        current_cost, curr = heapq.heappop(pq)

        if curr == m:
            return current_cost

        if current_cost > dist.get(curr, float('inf')):
            continue

        # 取得當前數字的各個位數
        s_curr = str(curr)
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # 嘗試增加 1 (不能是 9)
            if digit < 9:
                next_val = int(s_curr[:i] + str(digit + 1) + s_curr[i+1:])
                if not is_prime[next_val]:
                    new_cost = current_cost + next_val
                    if new_cost < dist.get(next_val, float('inf')):
                        dist[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))

            # 嘗試減少 1 (不能是 0)
            if digit > 0:
                next_val = int(s_curr[:i] + str(digit - 1) + s_curr[i+1:])
                if not is_prime[next_val]:
                    new_cost = current_cost + next_val
                    if new_cost < dist.get(next_val, float('inf')):
                        dist[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))

    return -1
```

