from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # offline_until stores the timestamp when a user will become online again
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp. If timestamps are equal, OFFLINE must come first 
    # (though problem says status change is processed before messages at same time).
    # Actually, we just need to process all events in chronological order.
    sorted_events = sorted(events, key=lambda x: int(x[1]))

    for type, ts_str, content in sorted_events:
        ts = int(ts_str)
        if type == "OFFLINE":
            uid = int(content.split('id')[1])
            offline_until[uid] = ts + 60
        else:
            tokens = content.split()
            for token in tokens:
                if token == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif token == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= ts:
