        if e_type == "OFFLINE":
            user_id = int(content.split()[0].replace("id", ""))
            online_until[user_id] = ts + 60
        else:
            tokens = content.split()
            for token in tokens:
                if token == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
