```python
from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # offline_until stores the timestamp when a user becomes online again.
    # We use a dictionary to track only those who are currently/were recently offline.
    offline_until = {}

    # Sort events by timestamp first. 
    # If timestamps are equal, process "OFFLINE" before "MESSAGE".
    # Since 'O' > 'M', we sort using a custom key where OFFLINE is prioritized (0 < 1).
    sorted_events = sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

    for event_type, timestamp_str, content in sorted_events:
        ts = int(timestamp_str)

        if event_type == "OFFLINE":
            # The format for OFFLINE is ["OFFLINE", "timestamp", "id_i"]
            # Extract the id from "id_i"
            uid = int(content.replace("id", ""))
            offline_until[uid] = ts + 60
        else:
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                for i in range(numberOfUsers):
                    # User is online if they are not offline or their offline time has passed
                    if i not in offline_until or ts >= offline_until[i]:
                        mentions[i] += 1
            else:
                # Content contains tokens like "id1 id0"
                tokens = content.split()
                for token in tokens:
                    if token.startswith("id"):
                        uid = int(token[2:])
                        mentions[uid] += 1

    return mentions
