from typing import List

def maxValue(nums: List[int], k: int) -> int:
    n = len(nums)
    # The problem asks for a subsequence of size 2*x where 1 <= x <= k.
    # Let the indices be i_1 < i_2 < ... < i_x < i_{x+1} < ... < i_{2x}.
    # Value = (nums[i_1] | ... | nums[i_x]) ^ (nums[i_{x+1}] | ... | nums[i_{2x}])
    # This is equivalent to finding a split point p such that 
    # the first x elements are chosen from nums[:p] and 
    # the next x elements are chosen from nums[p:].

    # dp_left[p][x] = set of possible OR sums using exactly x elements from nums[0...p-1]
    dp_left = [[set() for _ in range(k + 1)] for _ in range(n + 1)]
    dp_left[0][0].add(0)
    for i in range(n):
        val = nums[i]
        # Copy previous results (not including nums[i])
        for x in range(k + 1):
            dp_left[i+1][x] |= dp_left[i][x]
        # Update with current val (including nums[i] as the x-th element)
        for x in range(k):
            for prev_or in dp_left[i][x]:
                dp_left[i+1][x+1].add(prev_or | val)

    # dp_right[p][x] = set of possible OR sums using exactly x elements from nums[p...n-1]
    dp_right = [[set() for _ in range(k + 1)] for _ in range(n + 2)]
    dp_right[n][0].add(0)
    for i in range(n - 1, -1, -1):
        val = nums[i]
        # Copy results from suffix (not including nums[i])
        for x in range(k + 1):
            dp_right[i][x] |= dp_right[i+1][x]
        # Update with current val (including nums[i] as the x-th element)
        for x in range(k):
            for prev_or in dp_right[i+1][x]:
                dp_right[i][x+1].add(prev_or | val)

    max_res = 0
    # Iterate over all possible split points p and sizes x
    # Group 1 indices: subset of {0, ..., p-1} with size x
    # Group 2 indices: subset of {p, ..., n-1} with size x
    for p in range(n + 1):
        for x in range(1, k + 1):
            if x <= p and (n - p) >= x:
                # Optimization: if both sets are empty, skip. 
                # But they won't be because we check x > 0.
                for or1 in dp_left[p][x]:
                    for or2 in dp_right[p][x]:
                        current_xor = or1 ^ or2
                        if current_xor > max_res:
                            max_res = current_xor

    return max_res

