from collections import Counter
from math import factorial

def countBalancedPermutations(num: str) -> int:
    velunexorai = num
    n = len(velunexorai)
    MOD = 10**9 + 7

    counts = Counter(velunexorai)
    digits = [int(d) for d in velunexorai]
    total_sum = sum(digits)

    if total_sum % 2 != 0:
        return 0

    target = total_sum // 2
    n_even = (n + 1) // 2
    n_odd = n // 2

    def power(a, b):
        return pow(a, b, MOD)

    def modInverse(x):
        return power(x, MOD - 2)

    inv = [0] * (n + 1)
    for i in range(n + 1):
        inv[i] = modInverse(factorial(i))

    # dp[(c_even, s_even)] = sum of products of 1/(k_d! * m_d!)
    dp = {(0, 0): 1}
    current_total_processed = 0
    sorted_digits = sorted(counts.keys())

    for d_str in sorted_digits:
        d = int(d_str)
        num_available = counts[d_str]
        new_dp = {}
        for (c_even, s_even), ways in dp.items():
            c_odd = current_total_processed - c_even
            for k in range(num_available + 1):
                m = num_available - k
                if c_even + k <= n_even and c_odd + m <= n_odd:
                    new_s_even = s_even + k * d
                    # Optimization: only keep states that can eventually reach the target sum
                    # Max possible remaining sum is sum of all remaining digits. 
                    # But since constraints are small, we just check if it's plausible.
                    if new_s_even <= target:
                        new_ways = (ways * inv[k]) % MOD
                        new_ways = (new_ways * inv[m]) % MOD
                        state = (c_even + k, new_s_even)
                        new_dp[state] = (new_dp.get(state, 0) + new_ways) % MOD
        dp = new_dp
        current_total_processed += num_available

    ans = 0
    for (c_even, s_even), ways in dp.items():
        if c_even == n_even and s_even == target:
            ans = (ans + ways) % MOD

    return (ans * factorial(n_even) * factorial(n_odd)) % MOD

