                return res
            else: # Only {carry, nums[idx]} left
                return max(carry, nums[idx])
        else:
            # Options from {nums[idx], nums[idx+1], nums[idx+2]}
            if idx + 2 < n:
                res = max(nums[idx], nums[idx+1]) + solve_final(idx + 3, nums[idx+2])
