from typing import List

def maxDistance(side: int, points: List[List[int]], k: int) -> int:
    n = len(points)
    # Precompute all pairwise Manhattan distances
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            d = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            dist[i][j] = dist[j][i] = d

    # Binary search on the answer
    def can_place(min_d):
        # Since k is very small (<= 25), use backtracking with pruning
        selected = []
        def backtrack(idx):
            if len(selected) == k:
                return True
            if idx == n:
                return False

            # Pruning: if remaining points are not enough to reach k
            if len(selected) + (n - idx) < k:
                return False

            for i in range(idx, n):
                can_pick = True
                for s in selected:
                    if dist[i][s] < min_d:
                        can_pick = False
                        break
                if can_pick:
                    selected.append(i)
                    if backtrack(i + 1):
                        return True
                    selected.pop()
            return False

        # Optimization: start from points with higher degrees or just try all
        return backtrack(0)

    # Collect all possible distances to binary search over
    all_dists = sorted(list(set(dist[i][j] for i in range(n) for j in range(i + 1, n))))

    low = 0
    high = len(all_dists) - 1
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        if can_place(all_dists[mid]):
            ans = all_dists[mid]
            low = mid + 1
        else:
            high = mid - 1

    return ans
```

這是一個典型的「最大化最小值」問題，結合了二分搜尋（Binary Search）與 backtracking/DFS 檢查。由於 $k$ 非常小（最大 25），我們可以使用二分搜尋距離 $d$，並用 DFS 來判斷是否存在 $k$ 個點彼此間的曼哈頓距離都 $\ge d$。

```python
from typing import List

def maxDistance(side: int, points: List[List[int]], k: int) -> int:
    # 預先計算所有兩兩之間的曼哈頓距離，減少重複計算
    n = len(points)
    dist_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            d = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            dist_matrix[i][j] = dist_matrix[j][i] = d

    def can_place(idx: int, count: int, current_selection: List[int], min_d: int) -> bool:
        if count == k:
            return True
        # 剩餘點數不足以湊到 k 個，直接回傳
        if count + (n - idx) < k:
            return False

        for i in range(idx, n):
            # 檢查當前點與已選中的點距離是否都 >= min_d
            is_valid = True
            for selected_idx in current_selection:
                if dist_matrix[i][selected_idx] < min_d:
                    is_valid = False
                    break

            if is_valid:
                current_selection.append(i)
                if can_place(i + 1, count + 1, current_selection, min_d):
                    return True
                current_selection.pop()
        return False

    # 二分搜尋範圍：0 到 2 * side (最大曼哈頓距離)
    low = 0
    high = 2 * side
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        if mid == 0:
            ans = max(ans, 0)
            low = 1
            continue

        # 使用 DFS 檢查是否存在符合條件的選法
        if can_place(0, 0, [], mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    return ans
```

