from typing import List

def maxDistance(side: int, points: List[List[int]], k: int) -> int:
    # Pre-calculate all pairwise Manhattan distances to get a candidate set for binary search
    # However, since side can be 10^9, we use the range of possible distances [0, 2*side]
    # and binary search. To optimize the check, we need an efficient backtracking.

    def check(min_d):
        n = len(points)
        selected = []

        def backtrack(start_idx):
            if len(selected) == k:
                return True

            # Pruning: if remaining points are not enough to reach k
            if len(selected) + (n - start_idx) < k:
                return False

            for i in range(start_idx, n):
                p1 = points[i]
                is_valid = True
                for p2 in selected:
                    if abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) < min_d:
                        is_valid = False
                        break

                if is_valid:
                    selected.append(p1)
                    if backtrack(i + 1):
                        return True
                    selected.pop()
            return False

        # Heuristic: Sorting points by x then y helps in some spatial pruning cases
        return backtrack(0)

    # Sort points to improve search consistency
    points.sort()

    low = 0
    high = 2 * side
    ans = 0

    # Use a more efficient check for the binary search:
    # Since k is very small (up to 25), we can use backtracking with pruning.
    while low <= high:
        mid = (low + high) // 2
        if mid == 0:
            ans = max(ans, 0)
            low = 1
            continue

        # Optimization for the check function to handle k up to 25
        # We use a simple backtracking but with an added check for remaining points
        def solve_backtrack(idx, current_count):
            if current_count == k:
                return True
            if idx == len(points) or (current_count + (len(points) - idx) < k):
                return False

            for i in range(idx, len(points)):
                p1 = points[i]
                valid = True
