                        valid = False
                        break
                if valid:
                    selected_pts.append(p1)
                    if solve_backtrack(i + 1, current_count + 1):
                        return True
                    selected_pts.pop()
            return False

        selected_pts = []
        if solve_backtrack(0, 0):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    return ans

